pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e36);

        // Adversarial counterparty: refuses payments of zero value.
        ZeroHater foe = new ZeroHater(c);
        address actor = address(foe);

        vm.deal(actor, amount);
        foe.deposit{value: amount}();
        assertTrue(c.getBalance(actor) == amount, "setup: deposit recorded");

        foe.attack();

        // General rule: after a withdrawal attempt completes, the caller's
        // recorded balance on c is always zero. The reference sends the full
        // nonzero balance (success => zeroed) or, for a zero balance, was
        // already zero. The mutant pays 0 (zeroing first), the callee reverts,
        // the whole withdrawal reverts, and the balance stays positive.
        assertTrue(c.getBalance(actor) == 0, "withdrawal must end with the recorded balance zeroed");
    }
}

contract ZeroHater {
    C public c;
    constructor(C _c) { c = _c; }
    function deposit() external payable { c.addToBalance{value: msg.value}(); }
    function attack() external { c.withdrawBalance(); }
    fallback() external payable {
        require(msg.value > 0, "zero-value payment refused");
    }
}

