pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // EOA counterparty: plain calls to it succeed
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(actor, amount);

        // first guarded call: deposit
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // second guarded call: withdraw succeeds (lock released in C)
        vm.prank(actor);
        bool okW;
        try c.withdrawBalance() { okW = true; } catch { okW = false; }
        assertTrue(okW, "withdraw should succeed");

        // lock must be released after the guarded call completes: a fresh guarded call succeeds in C
        vm.deal(actor, 1);
        vm.prank(actor);
        bool ok2;
        try c.addToBalance{value: 1}() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "reentrancy lock must be released after each guarded call");
    }
}

